(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["az"] = {"ui":{"skip":"Məzmuna keç","back":"← AI-gile-a qayıt","lang.button":"Dil: {name}","lang.dialog":"Dil seç","lang.search":"Dil axtar","lang.none":"Heç bir dil uyğun gəlmir","lang.notYet":"{name} hələ tərcümə olunmayıb","theme.aria":"Temanı dəyiş: açıq, tünd və ya qara","theme.toLight":"Açıq temaya keç","theme.toDark":"Tünd temaya keç","theme.toBlack":"Qara temaya keç (əsl qara, OLED ekranlar üçün rahat)","words.underline":"Səhifədə bu sözlərin altından xətt çək","words.underlineHelp":"Mənasını görmək üçün nöqtəli sözün üzərinə gətir və ya ona toxun.","index.title":"AI-gile: süni intellekt komandan, bir lövhədə","index.description":"AI-gile süni intellektlə kodlayan komandalar üçün kanban lövhəsidir. Sən yatanda onlar işləyir; sənə qərar vermək, sınamaq və qəbul etmək üçün bir qısa yığın qalır.","hero.logoAlt":"AI-gile lövhə ikonu","hero.h1.html":"Süni intellekt komandan, bir&nbsp;lövhədə.","hero.alpha":"🐣 Qapalı pre-alfa","hero.alphaTitle":"Erkən və yarımçıq: sınadığın üçün sağ ol!","hero.lede":"Sən yatanda onlar qurur. Yuxudan durub bir qısa yığın görürsən: bir neçə sual, sınamalı bir neçə şey, bir-iki bənövşəyi almaz. Kliklə, qəbul et, çayına qayıt.","dl.windows":"Windows tətbiqi","dl.browser":"Brauzerində işlət","dl.soon":"Tezliklə","dl.notify":"🔔 Açılanda mənə xəbər ver","dl.notifySmall":"Alfa və ya beta","hero.secondary":"Çevik (agile) metoddur, amma komandanın ayaqüstü görüş qəhvəsinə ehtiyacı yoxdur. (Yenə də ayaqüstü görüş keçirirlər.)","pitch.h2":"AI-gile istədiyin qədər sözlə","pitch.lede":"Uzunluğu seç, bir sözdən 144-ə qədər. Hər uzunluq həmin ölçü üçün yazılmış ayrıca təsvirdir. Sürüşdürücünü çək və ya ox düymələrindən istifadə et.","pitch.rangeLabel":"Uzunluq (sözlə)","pitch.dice":"🎲 başqa variant","pitch.words.one":"{n} söz","pitch.words.other":"{n} söz","pitch.letters.one":"{n} hərf","pitch.letters.other":"{n} hərf","pitch.chars.one":"{n} simvol","pitch.chars.other":"{n} simvol","count.line.html.one":"İndi lövhədə {n} kart var","count.line.html.other":"İndi lövhədə {n} kart var","features.aria":"Nə edir","f.pile.h":"Sənin üçün bir yığın","f.pile.html":"<b>Sənin üçün</b> bütün layihələr üzrə səni gözləyən hər şeyi saxlayır: suallar, sınanacaq şeylər, yalnız insanın edə biləcəyi işlər. Növbən nəyin sırada olduğunu və nə qədər çəkəcəyini deyir.","f.sleep.h":"Sən yatanda işləyən komandalar","f.sleep.p":"Hər layihənin lideri və süni intellekt agentlərindən ibarət komandası var. Karta rəy yaz, komanda oyanır, işi görür və yorğun insanın izləyə biləcəyi addımlarla geri verir.","f.tester.h":"Əvvəlcə süni intellekt test edən yoxlayır","f.tester.p":"Sənə heç nə çatmamış, test edən tətbiqin nüsxəsində addımları izləyir və gördüyünü ekran görüntüsü ilə göstərir. Keçənlərə göz gəzdir və bir kliklə qəbul et.","f.proof.h":"Söz yox, sübut","f.proof.p":"Hər təhvil nəyin dəyişdiyini göstərir: faylları, fərqi, ekran görüntülərini. İş bitibmi görmək üçün hər tətbiqi açmağa ehtiyac yoxdur.","f.chat.h":"Liderlərinlə söhbət et","f.chat.p":"Discord üslubunda yan sütun: hər layihəyə bir ikon, səni gözləyənlər üçün bənövşəyi almazlar. Liderə fikir yaz; o, onu kartlara və plana çevirir, ✅ Başla düyməsi ilə.","f.tidy.h":"Özünü səliqəyə salır","f.tidy.p":"Əlaqəli kartlar birləşir, qarışıq başlıqlar düzəlir, token yoxlaması isə kodu yığcam saxlayır. Keçid ediləcək şey azdır, düşünüləcək şey də.","f.private.h":"Sənindir, kompüterində","f.private.li1":"Lövhə öz maşınında işləyir və yalnız sənə cavab verir.","f.private.li2":"İnsanlar arasında şəxsi mesajlar uçdan-uca şifrələnir.","f.private.li3":"Hesab yoxdur, izləyici yoxdur, cookie yoxdur.","f.lang.h":"Öz dilində","f.lang.p":"Holland, Uels və Yapon dillərindən quldur, Yoda və Klinqon dillərinə qədər 120-dən çox dil, tərtibatçı sözləri üçün ingiliscəyə tez qayıtmaq imkanı ilə.","f.service.h":"İdeyadan əsl xidmətə","f.service.p":"AI ilə insanların indi istifadə etdiyi nəsə qurmusunuz? Onu xidmət kimi işarələyin, lövhə onu yaxşı işlətməyə kömək edəcək: işləmə yoxlamaları, açıq status səhifəsi, təhlili yazılan insidentlər, Go tələb edən dəyişikliklər, hər gün yoxlanan ehtiyat nüsxələr. Kömək hər addımı irəlilədikcə öyrədir.","tl.aria":"İlk söhbətdən yol xəritəsinə qədər zaman xətti","tl.h2":"İlk söhbətdən sonrakı addıma","tl.lede":"Həqiqi tarixlər və saatlar, öz saat qurşağında. Bu gündən sonra plandır, tarix vəd edilmir.","tl.today":"Bu gün","tl.planned":"planlaşdırılıb","tl.cards.one":"{n} kart","tl.cards.other":"{n} kart","join.h2":"Qoşul","join.lede":"AI-gile-ı kiçik bir insan və çoxlu səbirli agent qurur. Hələlik şəxsidir, dostlarla qapalı alfadadır. Açılanda sınamaq istərdin?","join.btn":"Maraq bildir","join.small":"Sənə e-poçt yazacağıq, başqa heç nə","footer.tag":"AI-gile. İzləyici yox, cookie yox, ayaqüstü görüş qəhvəsi yox.","footer.licence":"Biznes lisenziyası","footer.status":"Vəziyyət","footer.privacy":"Nə saxlayırıq","footer.thanks":"Zənglər ChilledChat sayəsində","form.sending":"Göndərilir…","form.failed":"Alınmadı: sonra yenidən yoxla.","form.offline":"AI-gile-a çatmaq olmadı: sonra yenidən yoxla.","form.keep":"Bunu yalnız sənə cavab vermək üçün istifadə edirik, sonra silirik. İzləyici yox, cookie yox.","form.keepLink":"Nə saxlayırıq","interest.title":"AI-gile: alfa açılanda mənə xəbər ver","interest.description":"AI-gile-ın qapalı alfası və ya betası açılanda xəbər tutmaq üçün e-poçtunu burax.","interest.h1":"🔔 Açılanda mənə xəbər ver","interest.lede":"AI-gile qapalı pre-alfadadır. E-poçtunu burax, sənin üçün yer olanda bir dəfə yazarıq.","interest.email":"E-poçtun","interest.which":"Hansı sınaq?","interest.alpha":"Qapalı alfa: erkən, kobud, çoxlu dəyişiklik","interest.beta":"Beta: daha sabit, sonra","interest.both":"Hansı əvvəl gəlsə","interest.submit":"Məni siyahıya yaz","interest.thanks":"Sağ ol! Siyahıdasan.","licence.title":"AI-gile: biznes lisenziyası","licence.description":"AI-gile-ı biznesində istifadə edirsən? Pulsuz biznes lisenziyası üçün müraciət et.","licence.h1":"📜 Biznes lisenziyası","licence.lede":"AI-gile-ı işdə istifadə edirsən? Kim olduğunu və nə etdiyini yaz. Bir xeyri toxunursa, lisenziya pulsuzdur.","licence.company":"Şirkət","licence.website":"Veb sayt","licence.what":"Nə ilə məşğulsan","licence.how":"Dünyaya necə kömək edir","licence.email":"E-poçt","licence.submit":"Müraciət et","licence.thanks":"Sağ ol! E-poçtla cavab verəcəyik.","status.title":"AI-gile vəziyyəti","status.h1":"AI-gile vəziyyəti","status.quiet":"Hər şey sakitdir","status.intro":"AI-gile indi işləyir? Bu səhifə hər 5 dəqiqədən bir saytı, lövhə paylaşımını, zəngləri və yükləməni yoxlayır.","status.up":"İşləyir ({ms} ms-də cavab verdi)","status.slow":"Son yoxlamaya cavab vermədi, yenidən yoxlanılır","status.down":"İşləmir: son iki yoxlamaya cavab vermədi","status.svc.web":"Sayt","status.svc.web.offers":"Bu sayt: AI-gile nədir və maraq forması","status.svc.boards":"Lövhə paylaşımı","status.svc.boards.offers":"İctimai lövhələr, dostlar arasında mesajlar və dəvətlər","status.svc.calls":"Zənglər","status.svc.calls.offers":"AI-gile-da səs, video və ekran paylaşımı","status.svc.download":"Yükləmə","status.svc.download.offers":"Windows quraşdırıcısı və dəvət linkləri","status.checking":"Yoxlanılır…","status.offline":"Vəziyyət xidmətinə indi çatmaq olmur (yenidən yoxlanılır)","status.updated":"yenilənib {ago}","status.justNow":"indicə","status.min":"{n} dəq əvvəl","status.hours":"{n} saat əvvəl","status.days":"{n} gün əvvəl","privacy.title":"AI-gile: nə saxlayırıq","privacy.h1":"Nə saxlayırıq","privacy.lede":"Qısası: yalnız bizə göndərdiyin, həm də uzun müddətə yox.","privacy.only":"Yalnız bizə göndərdiyin: formaya yazdığın, məsələn, e-poçtun. Sənin haqqında başqa heç nə.","privacy.sealed":"Serverimiz oxuya bilməsin deyə möhürlənir: göndərilməzdən əvvəl brauzerində (köhnə brauzerdə isə çatdığı an). Onu yalnız öz lövhəmiz aça bilər.","privacy.server":"Lövhəmizə çatan kimi serverdən silinir. 30 gündən sonra orada qalan hər şey onsuz da silinir.","privacy.board":"Onu lövhəmizdə yalnız sənə cavab verənə qədər saxlayırıq, sonra oradan da silirik.","privacy.none":"İzləyici yox, cookie yox, analitika yox.","privacy.local":"Dilin və açıq və ya tünd tema seçimin öz brauzerində qalır. Heç vaxt bizə göndərilmir.","privacy.ask":"Daha tez silinməsini istəyirsən? E-poçtumuza cavab yaz və bunu bildir.","live.h2":"Onun necə qurulduğunu canlı izləyin","live.caption":"Hər kart gizlidir: işin formasını görürsünüz, sözlərini yox.","live.watching.one":"canlı: {n} izləyir","live.watching.other":"canlı: {n} izləyir","live.last.now":"Son kart indicə köçürüldü","live.last.min.one":"Son kart {n} dəq əvvəl köçürüldü","live.last.min.other":"Son kart {n} dəq əvvəl köçürüldü","live.last.hour.one":"Son kart {n} saat əvvəl köçürüldü","live.last.hour.other":"Son kart {n} saat əvvəl köçürüldü","live.last.day.one":"Son kart {n} gün əvvəl köçürüldü","live.last.day.other":"Son kart {n} gün əvvəl köçürüldü","live.offline":"Canlı lövhə bir az nəfəs alır. Tezliklə yenidən baxın.","live.cols":"Backlog|Görüləcək|İcrada|Komanda yoxlayır|Sənin test etməyin üçün|Komanda üçün|Hazırdır"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotlar.","Həvalə."]},{"n":2,"texts":["Robot kanbanı.","Agentlər, nizamlı.","Fikirlər, qurulub."]},{"n":3,"texts":["Robotlar üçün kanban.","Fikirlər funksiyaya çevrilir.","Pulsuz agent kanbanı."]},{"n":5,"texts":["Agentlərin idarə etdiyi kanban lövhəsi.","Sən kart yazırsan. Agentlər qurur.","Pulsuz, lokal, sınaqdan keçmiş, azacıq əcaib."]},{"n":8,"texts":["Süni intellekt agentlərinin işlədiyi pulsuz kanban lövhəsi.","Fikir yaz. Agentlər onu qurur. Sən qəbul edirsən.","Bir insan və çoxlu səbirli robot üçün çeviklik."]},{"n":13,"texts":["Kompüterində olan kanban lövhəsi, kartları süni intellekt agentləri götürüb işləyir.","Fikir yaz. Agentlər komandası onu qurur. Test edən isə yoxlayır.","Pulsuz, hesabsız, izləyicisiz: bir lövhə, bir neçə robot və hər şeyi idarə edən sən."]},{"n":21,"texts":["AI-gile süni intellekt kodlama agentləri ilə işləmək üçün kanban lövhəsidir. Kartları onlar götürür, sən isə sınayıb qəbul edirsən.","Hər layihənin lideri və süni intellekt agentləri komandası olur. İstənilən karta rəy yaz, komanda dərhal işə başlayır.","Öz kompüterində işləyən pulsuz, şəxsi tapşırıq lövhəsi. İşçilər robotlardır. Hə deyən isə yalnız sənsən. Qərar həmişə səndədir."]},{"n":34,"texts":["Fikirləri lövhəyə qoyursan. Süni intellekt agentləri komandası onları işləyən funksiyalara çevirir, test edir və sınamaq üçün addımlarla geri qaytarır. Sən demədikcə heç nə bitmiş sayılmır. Hər şey şəffafdır.","AI-gile Richin indi idarə etdiyi agentlərin böyük köməyi ilə evdə düzəltdiyi kanban lövhəsidir. Pulsuzdur, kompüterində işləyir və dostlarla paylaşılır, satılmır. Bu, sadə, açıq və dostcasına bir layihədir, heç bir qəliz şərti yoxdur.","Backlogdan Bitdiyə qədər sütunları olan adi kanban lövhəsini təsəvvür et, yalnız kartları süni intellekt agentləri götürür. Gedişatı bildirir, ilişəndə soruşur və həmişə sənin razılığını gözləyir. Hər şey gözünün qabağındadır."]},{"n":55,"texts":["AI-gile komandası süni intellekt agentlərindən ibarət olan kanban lövhəsidir. Hər layihənin işi planlayan lideri və onu quran köməkçiləri var. Funksiya hazır olanda süni intellekt test edən onu sınayır və ekran görüntüsü çəkir, sonra o, sənin yığınına düşür. Qəbul et və ya rəy yaz, onlar yenidən işləsinlər. Heç nə gizlində baş vermir.","Hər şey bir nəfərin eyni vaxtda çoxlu süni intellekt kodlama sessiyasını izləmək üsulu kimi başladı və real lövhəyə çevrildi. Maşınında işləyir, hesab tələb etmir, izləyicisi yoxdur. Dostlar və maraqlananlar üçün pulsuzdur. Həm də yarımçıqdır, ona görə kobud yerlər və arabir sürprizlər gözlə. Bir sözlə, sakit və səmimi bir layihədir.","Budur dürüst variant. Fikirləri yenə də sən tapmalısan, nəticələri də yenə sən yoxlamalısan. AI-gile isə arada olan hər şeyi edir: kartları sıraya salır, rəy yazanda lazımi agenti oyadır, nəyin dəyişdiyini dəqiq göstərir və hamısını sənin üçün bir qısa yığında saxlayır. Qısası, hər şey sakit və aydın gedir."]},{"n":89,"texts":["AI-gile öz kompüterində işlətdiyin pulsuz kanban lövhəsidir. İnsanların əvəzinə hər layihənin süni intellekt agentləri komandası var: fikirlərini kartlara və plana çevirən lider və kartları prioritet sırası ilə götürən köməkçilər. Nəsə qurulanda süni intellekt test edən sınaq addımlarını izləyir və gördüyünü sənə göstərir. Sonra o, Sənin üçün adlı bir yığında gözləyir. Qəbul edirsən, ya da rəy yazırsan və komanda yenidən cəhd edir. Sənsiz heç nə heç vaxt Bitdi sütununa çatmır. Hamısı sənin kompüterində qalır.","Gözləmədiyin bəzi imkanlar var. Gecə növbəsi sən yatanda Görüləcək sütununu doldurur və səndən cavab tələb etməyən kartları seçir. Token sayğacı agentlərin bu gün və bu həftə nə qədər işlətdiyini göstərir, Tokensiz rejim isə onlara xərcləməyi dayandırmağı deyir. Dostlarına mesaj yaza bilərsən, şəxsi mesajlar uçdan-uca şifrələnir. Lövhə holland, flamand, quldur və klinqon daxil təxminən 120 dildə danışır. Bunların heç biri bir qəpik də tutmur, və heç kim də bunu sənə satmağa çalışmır. Yəni hər şey sakit və sadə qalır.","AI-gile kiçik, şəxsi layihədir, şirkət deyil. Rich bir neçə süni intellekt kodlama layihəsinə baxmaq istəyirdi, amma hər tətbiqi açıb yoxlamadan. Ona görə o və agentlər bunun üçün lövhə qurdular, sonra da lövhənin qalan hissəsini qurmaq üçün ondan istifadə etdilər. İndi qapalı pre-alfadadır, yəni bir ovuc dost üçün, əsasən, işləyir. Qiymət səhifəsi yoxdur, xəbər bülleteni yoxdur, böyümə planı yoxdur. Faydalı görünürsə, bir az daha açılanda sınamaq üçün xahiş edə bilərsən. Tələsmə, hər şey sakit gedir."]},{"n":144,"texts":["AI-gile bir insan və çoxlu süni intellekt agenti üçün kanban lövhəsidir. Öz kompüterində işləyir və tamamilə pulsuzdur. Layihələr əlavə edirsən, hər layihəyə lider və kiçik komanda düşür. Liderlə bir az Discord kimi söhbət edib fikri təsvir edirsən; lider onu kartlara və plana çevirir, sonra sənin Başla düyməsini basmağını gözləyir. Komanda kartları prioritet sırası ilə dil modelləri üçün hazırlanmış sadə əmr sətrindən istifadə edərək işləyir. Hər şey sənə qayıtmamışdan əvvəl süni intellekt test edən tətbiqin nüsxəsində addımları izləyir və ekran görüntüsü əlavə edir. Bitmiş iş dəyişən fayllar və fərqlə birlikdə sənin yığınına düşür. Qəbul edirsən, ya da rəy qoyursan, komanda oyanıb yenidən cəhd edir. Kartı Bitdi sütununa yalnız sən keçirə bilərsən. Hər şey əvvəldən axıra gözünün qabağındadır.","AI-gile ilə bir gün, təxminən. Axşam bir neçə rəy qoyursan: bu düymə yanlış yerdədir, bu siyahı sıralanmalıdır, tünd rejim ola bilərmi. Yatırsan. Agentlər rəyləri oxuyur, dəyişiklikləri edir, test edir və sənə qaytarır. Görüləcək sütunu boşalarsa, gecə növbəsi onu backlogdan səndən cavab tələb etməyən kartlarla doldurur. Səhər bir qısa yığın olur: bir neçə sual və sınamalı bir neçə şey, hər birinin yuxulu adamın izləyə biləcəyi addımları və işlədiyini göstərən ekran görüntüsü var. Kliklə keçirsən, yaxşıları qəbul edirsən, qalanını geri göndərirsən. Token sayğacı hamısının nə işlətdiyini göstərir, arıq həftələr üçün Tokensiz rejim var. Sonra səhər yeməyi yeyirsən, bunda agentlər hələ kömək edə bilmir. Bütün bunlar sənin öz tempində gedir: heç kim səni tələsdirmir, heç nə səni sıxmır. İstəsən, gün ərzində də baxa bilərsən, çünki hər şey həmişə yerindədir.","Əvvəlcə AI-gile nə deyil. O, startap deyil, satılmır və heç kim məlumatlarını toplamır. Kompüterində işləyən pulsuz lövhədir, hesabsız, izləyicisiz və cookie-siz. Nə isə: bütün süni intellekt kodlama layihələrini bir yerdə görmək üçün səliqəli bir məkan, kartları agentlər komandası edir, qərarları isə sən verirsən. Əlaqəli kartları birləşdirir, qarışıq başlıqları düzəldir və kodun nə qədər yığcam qaldığına nəzər salır. Holland və flamanddan quldur və klinqon dilinə qədər təxminən 120 dildə danışır. Dostlar bir-birinə şəxsi və şifrələnmiş mesaj yaza bilər. Onu Rich və çoxlu səbirli agent qurub, əsasən özündən istifadə edərək. Qapalı pre-alfadadır, ona görə yerlərdə kobuddur. Əgər əyləncəli görünürsə, nəzakətlə xahiş et, bəlkə erkən girdin. Dostların üçün qapı açıqdır. Maraqlanırsansa, bir az səbir et, tezliklə növbə sənə çatacaq, bir də yoxla."]}],"quips":{"1":"Bir söz. Cəsarətli. Bəlkə də çox cəsarətli.","3":"Üç söz. Artıq çox məhsul səhifəsindən dürüstdür.","8":"Səkkiz söz. Yenə də ayaqüstü görüşdən qısadır.","21":"Yeri gəlmişkən, uzunluqlar story point-dir. Əlbəttə ki, elədir.","55":"Əlli beş söz. Sən bunu oxuyanda iki kart bitdi.","144":"Bu uzun olanıdır. 233 yoxdur. Agentlər yatmağa gedib."}},"timeline":{"first-idea.name":"İlk fikir","first-idea.line":"Hələ heç bir kod olmadan ən ilk söhbət.","first-board.name":"İlk lövhə","first-board.line":"Öz qurulmasını izləyən lövhə: kartlar, sütunlar, sürüklə-burax, layihələr.","team-roles.name":"Komanda və rollar","team-roles.line":"Agent profilləri, komanda şablonları, məkanlar və kim nə edir.","install.name":"Quraşdırma və buraxılışlar","install.line":"Dostun quraşdıra biləcəyi zip, özünüyeniləmə, kanallar və geri qaytarma.","usage-saver.name":"İstifadə qənaəti","usage-saver.line":"İşə salmaların nəyə başa gəldiyini ölç, kodu yığcam saxla, limitini qoru.","friends.name":"Dostlar və paylaşım","friends.line":"Şəxsi mesajlar, şifrələnmiş relay, dəvətlər, rollar və paylaşılan layihələr.","languages.name":"Dillər","languages.line":"Hər ekran mətni dil faylında, əvvəlcə holland və flamand.","ai-tester.name":"Süni intellekt test edən","ai-tester.line":"Test edən hər təhvili əvvəlcə yoxlayır və gördüyünü göstərir.","website.name":"Veb sayt","website.line":"aigile.lol, təqdimat səhifəsi və bu zaman xətti.","streaming.name":"Söhbət və yayım","streaming.line":"Discord, Twitch, OBS, yayımçı rejimi, GIF-lər və emojilər.","no-ai.name":"Süni intellektsiz buraxılış","no-ai.line":"Süni intellektsiz kodlayanlar üçün lövhə və açıq lövhələr.","night-watch.name":"Gecə növbəsi","night-watch.line":"Növbətçi və Scrum Master sən yatanda komandaları işdə saxlayır.","p-more.name":"Qalan hər şey","p-more.line":"Növbəsini gözləyən kiçik fikirlər.","p-android.name":"Telefon və Android","p-android.line":"Lövhənə telefondan çat, sonra doğma Android tətbiqi.","p-release.name":"Alfa və sonrası","p-release.line":"Qapalı alfa, canlı sayt, sonra beta.","p-languages.name":"Daha çox dil","p-languages.line":"Yüzdən çox dil və öyrənənlər üçün dilə qərq olma rejimi.","p-engines.name":"Daha çox süni intellekt mühərriki","p-engines.line":"Hər agent üçün Claude, Codex və ya Gemini seç.","p-pro.name":"Peşəkar təcrübə","p-pro.line":"Risk etiketləri, birləşdirmə keçidləri, insident kartları və qoruyucu çərçivələr.","p-self.name":"Sənə qulluq","p-self.line":"Yorğunluq rejimi, özünə qayğı xatırlatmaları və 4:20.","p-servers.name":"Serverlər və miqyas","p-servers.line":"Qlobal server ayarları, rollar və böyümə planlaşdırması.","p-livestream.name":"Yayım əlavələri","p-livestream.line":"Twitch söhbəti, fərdi emojilər və açıq canlı baxış."},"words":{"button":"📖 Developer sözləri","h":"📖 Sözlərin izahı","intro":"AI-gile-da rastlaşdığınız sözlər, sadə dildə: qurmaq, təhlükəsiz dəyişmək, istifadə edən insanlar üçün işlək saxlamaq və AI ilə komanda kimi işləmək.","search":"Söz axtar…","none":"Belə söz yoxdur.","close":"Bağla","count":{"one":"{count} söz","other":"{count} söz"},"groups":[{"id":"build","name":"🛠️ Qurmaq"},{"id":"change","name":"🔀 Təhlükəsiz dəyişmək"},{"id":"run","name":"🛎️ Xidməti işlətmək"},{"id":"team","name":"🤝 Komanda kimi işləmək (və AI ilə)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Layihənin kod qovluğu və commit-lərin tam tarixçəsi, adətən GitHub-da da saxlanır.","also":["repozitoriya"]},{"id":"branch","g":"build","word":"Branch","text":"Kodda ayrıca iş xətti, beləliklə əsas versiyaya toxunmadan dəyişiklik etmək olar.","also":["branch-lər"]},{"id":"commit","g":"build","word":"Commit","text":"Kodun nəyin dəyişdiyinə dair qısa qeydlə saxlanmış anlıq görüntüsü. Həmişə ona qayıtmaq olar.","also":["commit-lər"]},{"id":"push","g":"build","word":"Push","text":"Saxlanmış görüntüləri (commit-ləri) bu kompüterdən GitHub-a göndərmək, beləliklə onlar ehtiyatda saxlanır və paylaşılır."},{"id":"merge","g":"build","word":"Merge","text":"Branch-dəki dəyişiklikləri əsas versiyaya geri birləşdirmək."},{"id":"pr","g":"build","word":"Pull request","text":"Branch-dəki dəyişikliklərin yoxlanıb əsas versiyaya birləşdirilməsini xahiş etmək.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodun nə etdiyini dəyişmədən səliqəyə salmaq: daha kiçik fayllar, daha aydın adlar, daha az təkrar."},{"id":"bug","g":"build","word":"Bug","text":"Olmalı olduğu kimi işləməyən şey.","also":["buglar"]},{"id":"test","g":"build","word":"Test","text":"Bitmiş işi qəbul etməzdən əvvəl istənilənə cavab verib-vermədiyini yoxlamaq üçün sınamaq.","also":["testlər"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Quality assurance (keyfiyyətin təminatı) sözünün qısaltması: hər hansı bir şey canlıya çıxmazdan əvvəl işləyən avtomatik yoxlamalar. QA qırmızıdırsa, nəsə alınmayıb və o düzəlməyənə qədər canlıya çıxa bilməz.","also":["keyfiyyət yoxlamaları","keyfiyyətin təminatı","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Yeni versiyanı canlıya çıxarmaq, məsələn insanların istifadə etdiyi serverə qoymaq."},{"id":"release","g":"change","word":"Buraxılış","text":"Birlikdə canlıya çıxan, adı olan bitmiş iş paketi, nəyin dəyişdiyi barədə qısa qeydlərlə. 🚀 Buraxılışlar qeydləri bitmiş kartlardan yazır.","also":["buraxılışlar","release"]},{"id":"rollback","g":"change","word":"Geri qaytarma","text":"Yeni versiya problem yaradanda işləyən son versiyaya qayıtmaq. AI-gile-da bu, hər dəyişikliyin üzərində yazılmış geri alma addımlarından yoxlama siyahısı hazırlayır.","also":["geri qaytar","rollback","roll back"]},{"id":"live","g":"change","word":"Canlı","text":"İnsanların istifadə etdiyi əsl versiya, sınaq üçün olan nüsxədən fərqli olaraq. Developerlər buna production (prod) da deyirlər.","also":["prod","production","canlı mühit","live"],"noTip":1},{"id":"change","g":"change","word":"Dəyişiklik","text":"İnsanların güvəndiyi bir şeydə planlaşdırılmış dəyişiklik, əvvəlcə yazılır: nə, niyə, risk, nə vaxt və necə geri qaytarılacaq. 🔀 Dəyişiklik təklif et ilə birini başladın.","also":["dəyişikliklər","dəyişiklik sorğusu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Pis gedə biləcək bir şey, nə qədər ehtimal olunduğuna və nə qədər pis olacağına görə xal alır. ⚠️ Risklər onları bir siyahıda saxlayır, ən yüksək xal əvvəldə, hər birinin yenidən baxmaq üçün tarixi var.","also":["risklər","risk reyestri"]},{"id":"chgwin","g":"change","word":"Dəyişiklik pəncərəsi","text":"Dəyişikliklərin canlıya çıxa biləcəyi vaxtlar, məsələn sakit bir çərşənbə axşamı, axşam saatlarında. Pəncərədən kənarda dəyişiklik kartı bitirilə bilməz, təcili hal olmadıqca.","also":["dəyişiklik pəncərələri","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Dəyişiklik canlıya çıxmazdan bir az əvvəl tez səsvermə: təsdiq etməli olan hər kəs Go və ya No go deyir. Yalnız hamı razılaşanda irəli gedir.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Təsdiq","text":"İş başlamazdan əvvəl “bəli” gözləmək. Dostun təklif etdiyi kart və ya dəyişiklik siz təsdiqləyənə və ya rədd edənə qədər ✅ Təsdiqlər bölməsində gözləyir.","also":["təsdiqlər","approval"]},{"id":"quiettime","g":"change","word":"Sakit vaxt","text":"Heç nəyin canlıya çıxmadığı bir müddət, məsələn yayım, demo və ya gecə. Komandalar işləməyə və sınamağa davam edir, amma canlıya çıxmaq o bitənə qədər gözləyir. Başqa yerlərdə buna dəyişiklik dondurulması (change freeze) deyilir.","also":["sakit vaxtlar","dəyişiklik dondurulması","change freeze"]},{"id":"service","g":"run","word":"Xidmət","text":"Qurduğunuz və insanların güvəndiyi bir şey, məsələn sayt və ya tətbiq, işləməyə davam etsin deyə qayğısına qalınır. “Bu layihə xidmətdir” qutusunu işarələyin və nə təklif etdiyini, kimin istifadə etdiyini və kimin növbədə olduğunu yazın.","also":["xidmətlər","service"]},{"id":"uptime","g":"run","word":"İşləmə yoxlaması","text":"Hər bir neçə dəqiqədən bir xidmətinizin hələ cavab verdiyini yoxlayan avtomatik yoxlama. Bir neçə dəfə ardıcıl alınmazsa, AI-gile özü insident kartı açır.","also":["işləmə vaxtı","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Status səhifəsi","text":"Xidmətin işləyib-işləmədiyini (yaşıl, narıncı və ya qırmızı) son yeniliklə göstərən açıq səhifə ki, istifadə edənlər soruşmaq əvəzinə baxa bilsinlər.","also":["status səhifələri","status page"]},{"id":"incident","g":"run","word":"İnsident","text":"Hazırda istifadə edənlər üçün xarab olan bir şey, məsələn saytın açılmaması. 🔥 İnsident kartı növbəni keçir: onu yenidən işlək etmək birinci gəlir.","also":["insidentlər","incident"]},{"id":"major","g":"run","word":"Böyük insident","text":"Böyük insident: çox insan təsirlənib, ya da pul və ya məlumat risk altındadır. Bir düymə bütün komandaları onun üzərinə qoyur (sürü), növbədə olanı oyadır və hər 30 dəqiqədən bir status yeniləməsi istəyir.","also":["böyük insidentlər","major incident"]},{"id":"oncall","g":"run","word":"Növbətçilik","text":"Nəsə xarab olanda, hətta gecə də, cavab verən adam olmaq. Hər xidmətin öz insidentləri üçün ilk oyadılan növbətçi komanda üzvü var.","also":["növbədə","növbətçi","on call","on-call"]},{"id":"replyby","g":"run","word":"Cavab vaxtı","text":"Kartın ilk cavab üçün nə qədər gözləyə biləcəyi, məsələn insident üçün bir saat. Ondan sonra qırmızı saat alır ki, heç nə səssizcə unudulmasın. Cavab hədəfi də deyilir.","also":["cavab vaxtları","cavab hədəfi","cavab hədəfləri"]},{"id":"postmortem","g":"run","word":"İnsident təhlili","text":"İnsidentdən sonra qısa geriyə baxış: nə baş verdi, nə kömək etdi və nəyi dəyişmək lazımdır, heç kimi günahlandırmadan. İnsident onsuz bağlana bilməz.","also":["post-mortem","postmortem","insidentdən sonrakı baxış"]},{"id":"problem","g":"run","word":"Problem","text":"Bir və ya bir neçə insidentin arxasındakı gizli səbəb. 🧩 Problem kartı təkrar-təkrar qayıdan insidentləri qruplaşdırır ki, səbəb tapılsın və birdəfəlik düzəldilsin.","also":["problemlər"],"noTip":1},{"id":"rootcause","g":"run","word":"Əsas səbəb","text":"Nəyinsə xarab olmasının əsl səbəbi, sadəcə gördüyünüz nasazlıq yox. Əsas səbəbi düzəldin, insident qayıtmağı dayandırar.","also":["əsas səbəblər","kök səbəb","root cause"]},{"id":"workaround","g":"run","word":"Müvəqqəti həll","text":"Əsl düzəliş hazır olana qədər işləri yürütmək yolu, məsələn ilişib qalanda nəyisə yenidən başlatmaq. Problem kartında yazılır ki, heç kim onu yenidən axtarmalı olmasın.","also":["müvəqqəti həllər","workaround"]},{"id":"knownerror","g":"run","word":"Məlum xəta","text":"Səbəbi bəlli olan və müvəqqəti həlli olan, amma hələ düzəlməyən problem. 🧩 Məlum xətalar onları sıralayır ki, hamı yenidən axtarmaq əvəzinə müvəqqəti həlldən istifadə etsin.","also":["məlum xətalar","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Məlum növ problemi düzəltmək üçün addım-addım təlimat, hər dəfə eyni qaydada, tez edilsin deyə. Böyük insidentdən sonra komanda sizin təsdiqiniz üçün birini təklif edə bilər.","also":["runbook-lar","təlimat"]},{"id":"backup","g":"run","word":"Ehtiyat nüsxə","text":"Məlumatlarınızın əvvəlki vaxtdan saxlanmış nüsxəsi, nəsə itərsə və ya zədələnərsə ona qayıtmaq üçün. AI-gile hər gün lövhələrinizin ehtiyat nüsxəsini çıxarır.","also":["ehtiyat nüsxələr","backup"]},{"id":"restore","g":"run","word":"Bərpa","text":"Məlumatları ehtiyat nüsxədən geri qaytarmaq. Ehtiyat nüsxə yalnız bərpa oluna bildiyini bildikdə həqiqətən sayılır, ona görə də arabir sınamağa dəyər.","also":["bərpa et","bərpa edildi","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Hələ planlaşdırılmamış fikirlər və işlər. «Görüləcək» sütununa keçməyincə orada heç nə üzərində işlənmir."},{"id":"sprint","g":"team","word":"Sprint","text":"Razılaşdırılmış kartlar dəstini bitirmək üçün qısa iş dövrü (çox vaxt bir-iki həftə).","also":["sprintlər"]},{"id":"standup","g":"team","word":"Stand-up","text":"Qısa görüş: komandanın hər üzvü nə etdi, sonra nə edəcək və nə mane olur.","also":["standup","stand-uplar"]},{"id":"kanban","g":"team","word":"Kanban","text":"Sütunları (Görüləcək, İcrada, Hazırdır) olan lövhə; iş getdikcə kartlar soldan sağa keçir."},{"id":"wip","g":"team","word":"WIP limit","text":"İcrada olan iş: sütunda ən çoxu neçə kart olmalıdır, beləliklə komanda yenisinə başlamazdan əvvəl başladığını bitirir.","also":["WIP"]},{"id":"dod","g":"team","word":"Tamamlandı tərifi","text":"Kart sizə verilməzdən əvvəl “bitdi”nin nə demək olduğunu göstərən qısa komanda siyahısı, məsələn sınanıb və izah olunub. Onun əkizi, Hazır tərifi, kartın başlamaq üçün nə vaxt kifayət qədər aydın olduğunu deyir.","also":["Hazır tərifi","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Sınaq yığını","text":"Sizin sınamağınızı gözləyən bitmiş kartlar, bir-birinin ardınca. Birini qəbul edin və ya qeydlə geri qaytarın, növbəti gəlir.","also":["sınaq yığınları","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Komandanın necə işlədiyinə geriyə baxış, daha yaxşı ediləcək bir şeydə razılaşmaq üçün. AI-gile-da retro komandanın iş qaydasına dəyişiklik təklif edir, siz isə Go və ya Hələ yox deyirsiniz.","also":["retrolar","retrospektiv"]},{"id":"peerreview","g":"team","word":"Həmkar yoxlaması","text":"İkinci cüt göz: başqa AI hər kartın işini sizə çatmazdan əvvəl yoxlayır ki, daha az səhv keçsin.","also":["kod yoxlaması","peer review","code review"]},{"id":"swarm","g":"team","word":"Sürü","text":"Hamı bir yerə: hər komanda başqa işini buraxıb həll olunana qədər bir təcili layihəyə kömək edir. Digər layihələr bu arada gözləyir.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"İşin axmasını təmin edən: ilişmiş kartları görür, komandaları tərpədir və sizə nəyin gözlədiyini xatırladır. AI-gile-da Lead Scrum Master bunu bütün layihələrdə edir.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Tapşırıq üzərində müstəqil işləyən AI: kodu oxuyur, dəyişikliklər edir, yoxlamalar aparır və hesabat verir.","also":["agentlər"]},{"id":"token","g":"team","word":"Token","text":"AI istifadəsinin sayıldığı vahid: təxminən oxunan və ya yazılan mətnin bir neçə hərfi. Token az olsa, planından daha çox qalır.","also":["tokenlər"]},{"id":"hook","g":"team","word":"Hook","text":"Müəyyən anda özü işləyən kiçik əmr, məsələn AI sessiyası başlayanda, beləliklə komanda şərhlərini eşidir.","also":["hook-lar"]}]}};
